function renderGlobalStatus(){const panel=document.querySelector('#global-analysis-status');if(!panel)return;panel.hidden=!analysisActive&&!state.analysisError;panel.classList.toggle('error',Boolean(state.analysisError));panel.querySelector('[data-progress-message]').textContent=state.analysisError||(analysisActive?(state.snapshot?'Пересчитываем план…':'Выполняется расчёт…'):'');}
