function bindScenario(container){const horizonField=container.querySelector('#horizon-days');horizonField.addEventListener('input',()=>{const checked=S.validateScenarioDraft(horizonField.value);state={...state,scenarioDraft:{horizonDays:horizonField.value,error:checked.error}};S.AppState=state;horizonField.setAttribute('aria-invalid',String(!checked.valid));let error=container.querySelector('#horizon-error');if(!checked.valid){if(!error){error=document.createElement('span');error.id='horizon-error';error.className='field-error';horizonField.after(error);}error.textContent=checked.error;horizonField.setAttribute('aria-describedby','horizon-error');}else{error?.remove();horizonField.removeAttribute('aria-describedby');state=S.updateScenario(state,{horizonDays:checked.value});S.AppState=state;updateStaleIndicators();}});const update=()=>setState(S.updateScenario(state,{includeInbound:container.querySelector('#include-inbound').checked}));container.querySelector('#include-inbound').addEventListener('change',update);container.querySelector('#recalculate')?.addEventListener('click',()=>{const checked=S.validateScenarioDraft(horizonField.value);if(!checked.valid){state={...state,scenarioDraft:{horizonDays:horizonField.value,error:checked.error}};render();document.querySelector('#horizon-days')?.focus();return;}runAnalysis();});}
